design.css:
/* Blossom — the Dantotsu look (docs/theme-references/dantotsu.md): pure black, one pink seed, Poppins, 16 px corners. */

/* Home opens on the profile: no app bar; its search and settings float over the banner as round buttons. */
@media (max-width: 640px) {
  [data-slot="home.header"] { position: absolute; inset: 0 0 auto; z-index: 5; padding: 12px 16px; pointer-events: none; }

  [data-slot="home.header"] a { pointer-events: auto; width: 52px; height: 52px; margin-left: 8px; border-radius: 999px; background: rgba(28, 28, 28, 0.9); }
}

/* The profile banner: full width, square, a slow Ken Burns drift, faded into the page. */
@keyframes blossom-ken-burns { from { transform: scale(1) translate(0, 0); } to { transform: scale(1.18) translate(-3%, -2%); } }
[data-slot="block.profile-header"] { padding: 0; }
[data-slot="block.profile-header"] > div { border-radius: 0; background: #000; overflow: hidden; }
[data-slot="block.profile-header"] [data-part="block.banner"] { animation: blossom-ken-burns 20s ease-in-out infinite alternate; }
[data-slot="block.profile-header"] > div > div:has(+ div) { background: linear-gradient(to top, #000 0%, rgba(0, 0, 0, 0.6) 45%, rgba(0, 0, 0, 0.1) 100%); }
[data-slot="block.profile-header"] [data-part="block.avatar"] { width: 52px; height: 52px; border: 0; }
[data-slot="block.profile-header"] [data-part="block.name"] { font-size: 18px; font-weight: 700; }
[data-slot="block.profile-header"] [data-part="block.stat"] { font-size: 12px; color: rgba(255, 255, 255, 0.58); }

/* Hub cards: two 72 px tiles, a centred uppercase label over a short pink underline. */
[data-slot="block.profile-header"] [data-nav-row] { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 16px; background: #000; }
[data-slot="block.profile-header"] [data-part="button"] {
  position: relative;
  display: grid;
  place-items: center;
  height: 72px;
  padding: 0 8px 6px;
  border-radius: 16px;
  background: linear-gradient(135deg, #2a1f27, #141014);
  backdrop-filter: none;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-align: center;
  text-transform: uppercase;
  color: #fff;
}
[data-slot="block.profile-header"] [data-part="button"]::after {
  content: "";
  position: absolute;
  bottom: 18px;
  left: calc(50% - 32px);
  width: 64px;
  height: 2px;
  border-radius: 2px;
  background: #ffaed9;
}

/* Rows: 16 px bold titles; covers float on a soft shadow; a pink score pill and an ongoing dot. */
[data-part="row.title"], [data-part="block.title"] { font-size: 16px; font-weight: 700; }
[data-part="blossom.cover"] > .theme-artwork { box-shadow: 0 8px 14px rgba(0, 0, 0, 0.55); }
[data-part="blossom.score"] { margin: 6px; background: #ffaed9; }
[data-part="blossom.ongoing"] { width: 16px; height: 16px; margin: 8px; border-radius: 999px; background: #7ee07e; border: 2px solid #000; }
[data-part="blossom.title"] { line-height: 1.25; min-height: 2.5em; }

/* Series page: the floating 16 px cover, a four-line title, the outlined full-width list button. */
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 16px; box-shadow: 0 16px 30px rgba(0, 0, 0, 0.6); }
[data-slot="detail"][data-variant="phone"] [data-part="detail.title"] { font-size: 16px; font-weight: 700; line-height: 1.4; -webkit-line-clamp: 4; color: #ebe0e2; }
[data-slot="detail"] [data-part="detail.alt-title"] { display: none; }
[data-part="detail.list-button"][data-variant="full"] { height: 48px; border: 1px solid #eee; border-radius: 16px; background: transparent; color: #dfbecd; font-size: 14px; font-weight: 700; letter-spacing: 0.1px; }

/* Facts as a table: a dim semi-bold label (synthetic-bold Poppins), a real-bold bright value at the
   end, Dantotsu's row order, and a pink accent on Score/Studio. */
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"] { font-weight: 600; color: rgba(237, 224, 230, 0.58); }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.value"] { font-weight: 700; text-align: end; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"] > * { order: 20; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="progress"] > * { order: 0; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="score"] > * { order: 1; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="status"] > * { order: 2; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="episodes"] > * { order: 3; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="duration"] > * { order: 4; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="format"] > * { order: 5; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="source"] > * { order: 6; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="studio"] > * { order: 7; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="season"] > * { order: 8; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="aired"] > * { order: 9; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="score"] [data-part="fact.value"],
[data-part="detail.facts"][data-variant="table"] [data-part="fact"][data-key="studio"] [data-part="fact.value"] { color: #ffaed9; }
[data-part="detail.facts"][data-variant="table"] { max-width: 560px; } /* desktop only in effect: the phone rule below runs it edge to edge */

/* The pill nav: only the active tab shows its label, uppercase and bold, with the line at the bottom edge. */
[data-slot="nav.bottom"] [data-part="nav.item.label"] { text-transform: uppercase; font-weight: 700; }
[data-slot="nav.bottom"] [data-part="nav.item"][data-active] > span:first-child:not([data-part]) { top: auto; bottom: 4px; left: 22px; right: 22px; height: 3px; }

/* ============================================================================================
   Series page, phone: Dantotsu's activity_media.xml + fragment_media_source.xml geometry.
   `detail.sections` puts INFO (facts/countdown/synopsis/genres) and WATCH (episodes) on their own
   tabs and folds relations/characters/recommended into INFO; `detail.continue: "card"` replaces the
   header Play button with the Continue card once something has aired. Everything below is scoped to
   the phone variant so the desktop series page (izumi's own 5-tab layout + card grid) is untouched.
   ============================================================================================ */
@keyframes blossom-ken-burns-banner { from { transform: scale(1.02) translate(0, 0); } to { transform: scale(1.16) translate(-3%, -2%); } }
@keyframes blossom-pop { 0% { transform: scale(0); } 61% { transform: scale(1.07); } 100% { transform: scale(1); } }
@keyframes blossom-page-zoom { 0% { transform: scale(1.3); } 61% { transform: scale(0.98); } 100% { transform: scale(1); } }
@keyframes blossom-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes blossom-indicator { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes blossom-tab-label { from { transform: translateY(20px); opacity: 0; } to { transform: none; opacity: 1; } }

/* Header stack: 32 px insets, a flex column. Natural DOM order already reads poster/title, [the rare
   pre-air CTA], ADD TO LIST, the access row, then the tabs — nothing here needs reordering once
   `sections.info: "overview"` moves the facts/synopsis/genres out into the Info tab. A 16 px gap plus
   the poster row's own -224 px pull-up lands ADD TO LIST flush with the banner's bottom edge:
   -224 (pull) + 160 (cover height) + 16 (gap) + 48 (button height) = 0. */
[data-slot="detail"][data-variant="phone"] > div:has(> div > [data-part="detail.poster"]) {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-inline: 32px;
}

/* Banner: 384 px + status bar, soft blur, a slow drift, faded to black over its whole height, plus a
   48 px scrim at the very top for the status-bar row. izumi's own short fade is redundant under it. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] {
  height: calc(384px + env(safe-area-inset-top));
  max-height: none;
  min-height: 0;
}
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] img {
  filter: blur(1.5px);
  animation: blossom-ken-burns-banner 25s ease-in-out infinite alternate;
}
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] > div:last-child { display: none; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: linear-gradient(to top, #000 0%, rgb(0 0 0 / 0) 100%);
  pointer-events: none;
}
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"]::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  z-index: 1;
  height: calc(48px + env(safe-area-inset-top));
  background-image: linear-gradient(to bottom, rgb(0 0 0 / 0.66), rgb(0 0 0 / 0));
  pointer-events: none;
}

/* Back chevron as a 32 px round button on the banner (undocumented selector: no detail.back hook yet). */
[data-slot="detail"][data-variant="phone"] > div:first-child button[aria-label="Back"] {
  width: 32px; height: 32px; margin: 8px; border-radius: 16px; background: #1c1c1c; color: #eee;
}

/* Cover + title, pulled up into the banner (see the container comment for the math). */
[data-slot="detail"][data-variant="phone"] > div > div:has(> [data-part="detail.poster"]) { margin-top: -224px; gap: 16px; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.poster"] {
  width: 108px; height: 160px; object-fit: cover; border-radius: 16px;
  box-shadow: 0 12px 24px rgb(0 0 0 / 0.5);
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.header"] { margin-top: 4px; }
[data-part="blossom.status"] { display: block; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* The header CTA now only ever shows pre-air (continue: "card" hides it once an episode is playable
   and the real Continue card takes over inside Watch), so it stays a plain pink button. */
[data-slot="detail"][data-variant="phone"] > div > [data-part="button"][data-variant="primary"] {
  margin-top: 0; border-radius: 16px; font-size: 14px; font-weight: 700;
}

/* ADD TO LIST: flush with the banner's bottom edge; `relative` + z-index because the banner is
   positioned and paints over static content otherwise. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.list-button"][data-variant="full"] {
  position: relative;
  z-index: 10;
  margin-top: 0;
  padding: 8px;
}

/* Access row: 60 px, icon-only 48 px circular buttons, right-aligned. The "Watched x out of y" text
   needs a header field the client doesn't expose yet (izumi has no per-series watched-count field) —
   see the report; the facts table's "Watched" row (below) carries the same number instead. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] { margin-top: 0; height: 60px; justify-content: flex-end; gap: 0; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[data-focusable] {
  flex: 0 0 48px; height: 48px; padding: 0; border-radius: 999px; background: transparent; color: #eee; font-size: 0;
}
[data-slot="detail"][data-variant="phone"] > div > div:has(> [data-part="tabs"]) { margin-top: 0; }

/* -- INFO tab content: countdown, facts table, synopsis, genres now render inside the Overview/Info
   section (`sections.info: "overview"`), so they just need their look, not a position in the header. -- */
[data-slot="detail"][data-variant="phone"] [data-part="detail.countdown"][data-variant="long"] {
  width: 100%; margin: 0; padding: 8px; border-radius: 0; background: transparent;
  text-align: center; font-size: 14px; font-weight: 700; text-transform: uppercase; color: rgb(238 238 238 / 0.38);
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.countdown"][data-variant="long"] > span { display: block; margin-top: 2px; font-size: 16px; color: #ebe0e2; }

[data-slot="detail"][data-variant="phone"] [data-part="detail.facts"][data-variant="table"] { max-width: none; margin: 0; row-gap: 0; column-gap: 16px; }

[data-slot="detail"][data-variant="phone"] button[data-part="detail.synopsis"] {
  margin-top: 0; padding: 16px 0; font-size: 14px; line-height: 1.45; color: #ebe0e2; text-indent: 24px; -webkit-line-clamp: 6;
}
[data-slot="detail"][data-variant="phone"] button[data-part="detail.synopsis"]::before {
  content: "Synopsis"; display: block; margin-bottom: 8px; text-indent: 0; font-size: 16px; font-weight: 700;
}

[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin: 8px 0 16px; padding: 0; overflow: visible;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"]::before { content: "Genres"; grid-column: 1 / -1; font-size: 16px; font-weight: 700; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] > [data-part="chip"] {
  display: grid; place-items: center; height: 46px; padding: 0 12px; border: 0; border-radius: 16px;
  background-image: linear-gradient(135deg, #2a1f27, #141014);
  font-size: 14px; font-weight: 700; text-transform: uppercase; color: #eee;
}

/* -- Page tab bar (section 4): icon-only inactive tabs, label-only active tab, a full-width 3 px line
   at the TOP edge of the active tab, 64 px tall. `data-tab` (from `sections.labels`) keys the icons. -- */
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] {
  height: calc(64px + env(safe-area-inset-bottom)); border-top: 0; background: #000; backdrop-filter: none;
}
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"] {
  position: relative; height: 64px; padding: 0; white-space: nowrap;
  font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 0; color: #ffaed9;
}
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"]:not([data-active]) { font-size: 0; color: #ebe0e2; }
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"]:not([data-active])::after {
  content: ""; position: absolute; top: 20px; left: calc(50% - 11px); width: 22px; height: 22px;
  background-color: currentColor;
  -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-position: center; mask-position: center;
  -webkit-mask-size: 22px; mask-size: 22px;
}
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-tab="overview"]:not([data-active])::after {
  -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2024%2024%22%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%229%22%20fill=%22none%22%20stroke=%22black%22%20stroke-width=%221.6%22/%3E%3Crect%20x=%2211%22%20y=%229.5%22%20width=%222%22%20height=%227%22%20rx=%221%22/%3E%3Ccircle%20cx=%2212%22%20cy=%226.6%22%20r=%221.5%22/%3E%3C/svg%3E);
  mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2024%2024%22%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%229%22%20fill=%22none%22%20stroke=%22black%22%20stroke-width=%221.6%22/%3E%3Crect%20x=%2211%22%20y=%229.5%22%20width=%222%22%20height=%227%22%20rx=%221%22/%3E%3Ccircle%20cx=%2212%22%20cy=%226.6%22%20r=%221.5%22/%3E%3C/svg%3E);
}
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-tab="episodes"]:not([data-active])::after {
  -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2024%2024%22%3E%3Crect%20x=%223%22%20y=%224%22%20width=%2218%22%20height=%2216%22%20rx=%223%22%20fill=%22none%22%20stroke=%22black%22%20stroke-width=%221.6%22/%3E%3Cpath%20d=%22M10%209l6%203-6%203z%22/%3E%3C/svg%3E);
  mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2024%2024%22%3E%3Crect%20x=%223%22%20y=%224%22%20width=%2218%22%20height=%2216%22%20rx=%223%22%20fill=%22none%22%20stroke=%22black%22%20stroke-width=%221.6%22/%3E%3Cpath%20d=%22M10%209l6%203-6%203z%22/%3E%3C/svg%3E);
}
[data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-active]::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px; border-radius: 0 0 3px 3px; background: #ffaed9;
}

/* -- WATCH tab: the Continue card, the "Episodes" heading row + Options overflow menu, range chips. -- */
[data-slot="detail"][data-variant="phone"] [data-part="episode.continue"] { height: 80px; border-radius: 16px; }
[data-slot="detail"][data-variant="phone"] [data-part="episode.continue.label"] { font-size: 14px; font-weight: 700; }
[data-slot="detail"][data-variant="phone"] [data-part="episode.continue.title"] { font-size: 12px; font-weight: 600; }
[data-slot="detail"][data-variant="phone"] [data-part="episode.continue"][data-filler]::after {
  content: ""; position: absolute; inset: 0 auto 0 0; z-index: 5; width: 4px; background: rgb(255 107 8 / 0.9);
}

[data-part="episodes.heading"] { font-size: 16px; font-weight: 700; }
[data-part="episodes.count"] { font-size: 13px; font-weight: 700; }

[data-slot="detail"][data-variant="phone"] [data-part="episodes.ranges"] { margin-inline: -32px; padding-inline: 32px; }
[data-part="episodes.ranges"] [data-part="chip"] {
  height: 32px; padding: 0 14px; border: 1px solid #890064; border-radius: 8px;
  background: #000; color: #858585; font-size: 14px; font-weight: 700;
}
[data-part="episodes.ranges"] [data-part="chip"][data-active] { background: #b3aead; color: #000; border-color: #890064; }

/* -- Episode LIST cards (a 164×109 still, a corner number tab, synopsis under the row, a whole-card
   dim for watched episodes and an orange tint for fillers — layered via z-index, see the report). -- */
[data-slot="detail.episodes"] div:has(> div > [data-part="episode"][data-variant="template"]) { gap: 16px; padding-inline: 0; }
[data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="template"]) { animation: none; }
[data-part="episode"][data-variant="template"] { position: relative; border-radius: 16px; background: #1c1c1c; }
[data-part="episode"][data-variant="template"][data-filler]::before {
  content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit; background: rgb(255 107 8 / 0.16); pointer-events: none;
}
[data-part="episode"][data-variant="template"][data-state="watched"]::after {
  content: ""; position: absolute; inset: 0; z-index: 5; border-radius: inherit; background: rgb(0 0 0 / 0.33); pointer-events: none;
}

[data-part="blossom.ep-head"] { flex-wrap: nowrap; padding-bottom: 4px; }
[data-part="blossom.ep-thumb"] { flex: 0 0 164px; width: 164px; height: 109px; border-radius: 16px; background: #000; }
[data-part="episode.still"] { height: 100%; }
[data-part="episode.number"] {
  padding: 1px 8px 0 6px; border-radius: 0 0 16px 0; background: #ebe0e2; color: #000;
  font-size: 20px; font-weight: 700; line-height: 30px;
}
[data-part="blossom.ep-progress"] { height: 2px; min-height: 2px; border-radius: 0; background: rgb(255 255 255 / 0.5); }
[data-part="blossom.ep-progress"] > span { background: #ffaed9; }
[data-part="blossom.ep-rating"] {
  margin: 4px; padding: 2px 4px; gap: 0; border-radius: 6px; background: rgb(0 0 0 / 0.7);
  color: #fff; font-size: 10px; font-weight: 700; line-height: 1.4;
}
[data-part="blossom.ep-text"] { flex: 1 1 0; min-width: 0; margin: 8px 0; padding: 0 8px 0 4px; }
[data-part="blossom.ep-filler"] { margin-bottom: 2px; font-style: italic; opacity: 0.75; }
[data-part="episode.title"] { line-height: 15px; }
[data-part="blossom.ep-date"] { margin-top: 2px; font-weight: 400; }
[data-part="blossom.ep-desc"] { line-height: 16px; }

/* Numbers layout = the reference's Compact: 4 columns of 64 px tiles (the watched/filler tint stays). */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="number"]) {
  grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px;
}
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"] { height: 64px; border-radius: 16px; font-size: 16px; font-weight: 700; }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"][data-filler] { background: rgb(255 107 8 / 0.16); }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"][data-state="watched"] { background: #1c1c1c; opacity: 0.6; }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"] > span { height: 2px; }

@media (prefers-reduced-motion: no-preference) {
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"],
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"],
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.characters"] {
    transform-origin: 50% 0;
    animation: blossom-page-zoom 300ms ease-out, blossom-fade 200ms ease-out;
  }
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] [data-part="episode"] { animation: blossom-pop 150ms ease-out; }
  [data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-active] { animation: blossom-tab-label 400ms cubic-bezier(.3, 1.35, .6, 1); }
  [data-slot="detail"][data-variant="phone"] [data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-active]::before { animation: blossom-indicator 400ms cubic-bezier(.3, 1.35, .6, 1); }
}
